test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 42500, discount: 0, total: 42500 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 42500 + 1960, discount: 0, total: 42500 + 1960 });
});

test('invoiceTotals with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 85000 + 3700, discount: 0, total: 85000 + 3700 });
});

test('invoiceTotals with empty lines returns 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 0, discount: 0, total: 0 });
});

