    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };
  // lineTotal: 42500, discount: 0, lineAfterDiscount: 42500, VAT: 42500 * 21 / 100 = 8925
  assert.deepEqual(invoiceTotals(invoice), { subtotal: 42500, discount: 0, vat: 8925, total: 51425 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
  };
  // Line 1: 42500 * 21 / 100 = 8925
  // Line 2: 1960 * 21 / 100 = 411.6 -> 412
  const subtotal = 42500 + 1960;
  const vat = 8925 + 412;
  assert.deepEqual(invoiceTotals(invoice), { subtotal, discount: 0, vat, total: subtotal + vat });
});

